import{_ as a,o as s,c as n,a as e}from"./app-eae545e9.js";const t={},p=e(`<h1 id="openssl生成证书" tabindex="-1"><a class="header-anchor" href="#openssl生成证书" aria-hidden="true">#</a> OpenSSL生成证书</h1><p>使用<code>openssl</code>套件进行证书生成，可用于网站，sftp等领域。</p><h2 id="_1-证书配置" tabindex="-1"><a class="header-anchor" href="#_1-证书配置" aria-hidden="true">#</a> 1 证书配置</h2><p>新建<code>yiueil-ca.cnf</code></p><div class="language-ini line-numbers-mode" data-ext="ini"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">req</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">distinguished_name</span> <span class="token punctuation">=</span> <span class="token value attr-value">req_distinguished_name</span>
<span class="token key attr-name">req_extensions</span> <span class="token punctuation">=</span> <span class="token value attr-value">v3_req</span>
<span class="token key attr-name">prompt</span> <span class="token punctuation">=</span> <span class="token value attr-value">no</span>
<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">req_distinguished_name</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">C</span> <span class="token punctuation">=</span> <span class="token value attr-value">CN</span>
<span class="token key attr-name">ST</span> <span class="token punctuation">=</span> <span class="token value attr-value">Yunnan</span>
<span class="token key attr-name">L</span> <span class="token punctuation">=</span> <span class="token value attr-value">Kunming</span>
<span class="token key attr-name">O</span> <span class="token punctuation">=</span> <span class="token value attr-value">YIueil</span>
<span class="token key attr-name">CN</span> <span class="token punctuation">=</span> <span class="token value attr-value">YIueil Root CA</span>
<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">v3_req</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">basicConstraints</span> <span class="token punctuation">=</span> <span class="token value attr-value">critical, CA:TRUE</span>
<span class="token key attr-name">keyUsage</span> <span class="token punctuation">=</span> <span class="token value attr-value">critical, keyCertSign, cRLSign, digitalSignature, keyEncipherment</span>
<span class="token key attr-name">extendedKeyUsage</span> <span class="token punctuation">=</span> <span class="token value attr-value">serverAuth, clientAuth</span>
<span class="token key attr-name">subjectAltName</span> <span class="token punctuation">=</span> <span class="token value attr-value">@alt_names</span>
<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">alt_names</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">DNS.1</span> <span class="token punctuation">=</span> <span class="token value attr-value">yiueil.cc</span>
<span class="token key attr-name">DNS.2</span> <span class="token punctuation">=</span> <span class="token value attr-value">*.yiueil.cc</span>
<span class="token key attr-name">IP.1</span> <span class="token punctuation">=</span> <span class="token value attr-value">47.109.40.4</span>
<span class="token key attr-name">IP.2</span> <span class="token punctuation">=</span> <span class="token value attr-value">192.168.193.8</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_2-生成命令" tabindex="-1"><a class="header-anchor" href="#_2-生成命令" aria-hidden="true">#</a> 2 生成命令</h2><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>openssl req <span class="token parameter variable">-x509</span> <span class="token parameter variable">-newkey</span> rsa:2048 <span class="token parameter variable">-keyout</span> yiueil-ca.key <span class="token parameter variable">-out</span> yiueil-ca.crt <span class="token parameter variable">-days</span> <span class="token number">3650</span> <span class="token parameter variable">-nodes</span> <span class="token punctuation">\\</span>
  <span class="token parameter variable">-config</span> yiueil-ca.cnf <span class="token parameter variable">-extensions</span> v3_req
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_3-验证" tabindex="-1"><a class="header-anchor" href="#_3-验证" aria-hidden="true">#</a> 3 验证</h2><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token shebang important">#!/bin/bash</span>
<span class="token assign-left variable">CERT</span><span class="token operator">=</span><span class="token string">&quot;yiueil-ca.crt&quot;</span>
<span class="token assign-left variable">KEY</span><span class="token operator">=</span><span class="token string">&quot;yiueil-ca.key&quot;</span>

<span class="token builtin class-name">echo</span> <span class="token string">&quot;========== 主题与颁发者 ==========&quot;</span>
openssl x509 <span class="token parameter variable">-in</span> <span class="token variable">$CERT</span> <span class="token parameter variable">-noout</span> <span class="token parameter variable">-subject</span> <span class="token parameter variable">-issuer</span>

<span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span>
<span class="token builtin class-name">echo</span> <span class="token string">&quot;========== 有效期 ==========&quot;</span>
openssl x509 <span class="token parameter variable">-in</span> <span class="token variable">$CERT</span> <span class="token parameter variable">-noout</span> <span class="token parameter variable">-dates</span>

<span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span>
<span class="token builtin class-name">echo</span> <span class="token string">&quot;========== CA 身份 ==========&quot;</span>
openssl x509 <span class="token parameter variable">-in</span> <span class="token variable">$CERT</span> <span class="token parameter variable">-noout</span> <span class="token parameter variable">-text</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-A1</span> <span class="token string">&quot;Basic Constraints&quot;</span>

<span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span>
<span class="token builtin class-name">echo</span> <span class="token string">&quot;========== Key Usage ==========&quot;</span>
openssl x509 <span class="token parameter variable">-in</span> <span class="token variable">$CERT</span> <span class="token parameter variable">-noout</span> <span class="token parameter variable">-text</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-A1</span> <span class="token string">&quot;Key Usage&quot;</span>

<span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span>
<span class="token builtin class-name">echo</span> <span class="token string">&quot;========== Extended Key Usage ==========&quot;</span>
openssl x509 <span class="token parameter variable">-in</span> <span class="token variable">$CERT</span> <span class="token parameter variable">-noout</span> <span class="token parameter variable">-text</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-A1</span> <span class="token string">&quot;Extended Key Usage&quot;</span>

<span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span>
<span class="token builtin class-name">echo</span> <span class="token string">&quot;========== SAN ==========&quot;</span>
openssl x509 <span class="token parameter variable">-in</span> <span class="token variable">$CERT</span> <span class="token parameter variable">-noout</span> <span class="token parameter variable">-text</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-A1</span> <span class="token string">&quot;Subject Alternative Name&quot;</span>

<span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span>
<span class="token builtin class-name">echo</span> <span class="token string">&quot;========== 证书与私钥匹配 ==========&quot;</span>
<span class="token assign-left variable">CERT_MD5</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span>openssl x509 <span class="token parameter variable">-noout</span> <span class="token parameter variable">-modulus</span> <span class="token parameter variable">-in</span> $CERT <span class="token operator">|</span> openssl md5<span class="token variable">)</span></span>
<span class="token assign-left variable">KEY_MD5</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span>openssl rsa <span class="token parameter variable">-noout</span> <span class="token parameter variable">-modulus</span> <span class="token parameter variable">-in</span> $KEY <span class="token operator">|</span> openssl md5<span class="token variable">)</span></span>
<span class="token builtin class-name">echo</span> <span class="token string">&quot;证书: <span class="token variable">$CERT_MD5</span>&quot;</span>
<span class="token builtin class-name">echo</span> <span class="token string">&quot;私钥: <span class="token variable">$KEY_MD5</span>&quot;</span>
<span class="token keyword">if</span> <span class="token punctuation">[</span> <span class="token string">&quot;<span class="token variable">$CERT_MD5</span>&quot;</span> <span class="token operator">=</span> <span class="token string">&quot;<span class="token variable">$KEY_MD5</span>&quot;</span> <span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token keyword">then</span>
    <span class="token builtin class-name">echo</span> <span class="token string">&quot;✅ 匹配成功&quot;</span>
<span class="token keyword">else</span>
    <span class="token builtin class-name">echo</span> <span class="token string">&quot;❌ 不匹配，请检查&quot;</span>
<span class="token keyword">fi</span>

<span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span>
<span class="token builtin class-name">echo</span> <span class="token string">&quot;========== 自签名验证 ==========&quot;</span>
openssl verify <span class="token parameter variable">-CAfile</span> <span class="token variable">$CERT</span> <span class="token variable">$CERT</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_4-转换给tomcat使用" tabindex="-1"><a class="header-anchor" href="#_4-转换给tomcat使用" aria-hidden="true">#</a> 4 转换给Tomcat使用</h2><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 执行后会需要新增一个证书密码</span>
openssl pkcs12 <span class="token parameter variable">-export</span> <span class="token parameter variable">-in</span> yiueil-ca.crt <span class="token parameter variable">-inkey</span> yiueil-ca.key <span class="token parameter variable">-out</span> yiueil-ca.p12 <span class="token parameter variable">-name</span> <span class="token string">&quot;yiueil&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>修改<code>Tomcat</code>配置<code>server.xml</code>并重启：</p><div class="language-xml line-numbers-mode" data-ext="xml"><pre class="language-xml"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>Connector</span> <span class="token attr-name">port</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>8443<span class="token punctuation">&quot;</span></span> <span class="token attr-name">protocol</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>org.apache.coyote.http11.Http11NioProtocol<span class="token punctuation">&quot;</span></span>
           <span class="token attr-name">maxThreads</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>150<span class="token punctuation">&quot;</span></span> <span class="token attr-name">SSLEnabled</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>true<span class="token punctuation">&quot;</span></span> <span class="token attr-name">scheme</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>https<span class="token punctuation">&quot;</span></span> <span class="token attr-name">secure</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>true<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>SSLHostConfig</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>Certificate</span> <span class="token attr-name">certificateKeystoreFile</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/path/to/your/yiueil-ca.p12<span class="token punctuation">&quot;</span></span>
                     <span class="token attr-name">certificateKeystorePassword</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>你设置的导出密码<span class="token punctuation">&quot;</span></span>
                     <span class="token attr-name">certificateKeystoreType</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>PKCS12<span class="token punctuation">&quot;</span></span>
                     <span class="token attr-name">certificateKeyAlias</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>yiueil<span class="token punctuation">&quot;</span></span>
                     <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>RSA<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>SSLHostConfig</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>Connector</span><span class="token punctuation">&gt;</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,13),l=[p];function i(o,c){return s(),n("div",null,l)}const u=a(t,[["render",i],["__file","OpenSSLshengchengzhengshu.html.vue"]]);export{u as default};
